SELECT CASE WHEN quantity >= 234 THEN 'high' WHEN quantity >= 80 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity, SUM(SUM(quantity)) OVER (ORDER BY CASE WHEN quantity >= 234 THEN 'high' WHEN quantity >= 80 THEN 'mid' ELSE 'low' END) AS cumulative_quantity FROM inventory WHERE product_id IN (5, 7) GROUP BY CASE WHEN quantity >= 234 THEN 'high' WHEN quantity >= 80 THEN 'mid' ELSE 'low' END ORDER BY cumulative_quantity;
